UserObject.plantUmlData:
{
  "data": "@startuml D50
skinparam monochrome true
title Диаграмма 50/62 — UC-25. Пересмотр отклонённых проектов (деятельность)
|Модератор|
start
:Открыть вкладку «Отклонённые»;
|Система|
if (Роль\nмодератора?) then ([нет])
  :Вернуть 403;
  |Модератор|
  :Доступ к списку запрещён;
  stop
else ([да])
  |Система|
  :Загрузить проекты со статусом rejected;
  :Показать причины и даты отклонения;
  |Модератор|
  while (Есть проекты\nдля пересмотра?) is ([да])
    :Открыть карточку проекта;
    :Прочитать причину отклонения;
    :Проверить устранение замечаний;
    if (Замечания\nустранены?) then ([да])
      :Нажать «Одобрить (пересмотр)»;
      |Система|
      :Изменить статус rejected на approved;
      :Записать moderated_at и moderator_id;
      fork
        :Опубликовать проект в каталоге;
      fork again
        :Обновить список отклонённых;
      end fork
      |Модератор|
      :Проект вернулся в каталог;
    else ([нет])
      :Оставить проект отклонённым;
      |Система|
      :Сохранить статус rejected и причину;
      |Модератор|
      :Проект остаётся в списке;
    endif
  endwhile ([нет])
  :Завершить пересмотр;
  stop
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D52
skinparam monochrome true
title Диаграмма 52/62 — UC-26. Модерация предложений тегов (деятельность)
|Модератор|
start
:Открыть вкладку «Предложения тегов»;
|Система|
if (Роль\nмодератора?) then ([нет])
  :Вернуть 403;
  |Модератор|
  :Доступ к очереди запрещён;
  stop
else ([да])
  |Система|
  :Загрузить очередь предложений;
  :Показать автора, проект\nи признак нового тега;
  |Модератор|
  while (В очереди есть\nпредложения?) is ([да])
    :Изучить название и описание тега;
    if (Тег\nуместен?) then ([да])
      :Нажать «Одобрить» и подтвердить;
      |Система|
      :Открыть транзакцию;
      :Прочитать данные предложения;
      if (Предложение\nактивно?) then ([нет])
        :Откатить транзакцию;
        :Вернуть 404 или 409;
      else ([да])
        if (Тег\nновый?) then ([да])
          :Создать тег в справочнике;
        else ([нет])
          :Использовать существующий тег;
        endif
        if (Проект\nуказан?) then ([да])
          :Привязать тег к проекту (UC-27);
        else ([нет])
        endif
        :Удалить предложение из очереди;
        :Зафиксировать транзакцию;
        :Обновить справочник и фильтры;
      endif
    else ([нет])
      |Модератор|
      :Нажать «Отклонить» и подтвердить;
      |Система|
      :Удалить предложение из очереди;
    endif
    :Обновить очередь предложений;
    |Модератор|
  endwhile ([нет])
  :Завершить разбор предложений;
  stop
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D54
skinparam monochrome true
title Диаграмма 54/62 — UC-27. Привязка тега к проекту (деятельность)
|Модератор|
start
if (Контекст —\nсоздание проекта?) then ([да])
  :Отметить теги в форме проекта;
  :Отправить форму проекта;
else ([нет])
  :Одобрить предложение тега (UC-26);
endif
|Система|
if (Роль\nмодератора?) then ([нет])
  :Вернуть 403;
  |Модератор|
  :Привязка отклонена;
  stop
else ([да])
  |Система|
  :Определить project_id и tag_id;
  if (Проект и тег\nсуществуют?) then ([нет])
    :Вернуть 400 или 404;
    |Модератор|
    :Привязка не выполнена;
    stop
  else ([да])
    |Система|
    :Выполнить INSERT product_tags\nON CONFLICT DO NOTHING;
    if (Связь уже\nбыла?) then ([да])
      :Сохранить связь без дублирования;
    else ([нет])
      :Создать новую связь тега с проектом;
    endif
    fork
      :Обновить блок тегов проекта;
    fork again
      :Обновить фильтры каталога;
    end fork
    |Модератор|
    :Тег привязан к проекту;
    stop
  endif
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D56
skinparam monochrome true
title Диаграмма 56/62 — UC-28. Удаление проекта, отзывов, комментариев (деятельность)
|Модератор|
start
:Выбрать объект удаления;
|Система|
:Запросить подтверждение необратимости;
if (Подтверждение\nполучено?) then ([нет])
  |Модератор|
  :Отменить удаление;
  stop
else ([да])
  |Система|
  if (Удаляется\nпроект?) then ([да])
    if (Роль\nмодератора?) then ([нет])
      :Вернуть 403;
      |Модератор|
      :Удаление отклонено;
      stop
    else ([да])
      |Система|
      :Удалить запись проекта;
      :Каскадно удалить отзывы,\nкомментарии и связи тегов;
      :Обновить каталог и счётчики;
      |Модератор|
      :Проект исчез из каталога;
      stop
    endif
  elseif (Удаляется\nотзыв?) then ([да])
    |Система|
    if (Автор или\nмодератор?) then ([нет])
      :Вернуть 403;
      |Модератор|
      :Удаление отклонено;
      stop
    else ([да])
      |Система|
      :Удалить запись reviews;
      :Пересчитать рейтинг и число отзывов;
      :Обновить список отзывов;
      |Модератор|
      :Отзыв удалён;
      stop
    endif
  else ([нет])
    |Система|
    if (Автор или\nмодератор?) then ([нет])
      :Вернуть 403;
      |Модератор|
      :Удаление отклонено;
      stop
    else ([да])
      |Система|
      :Удалить комментарий вместе с ответами;
      :Пересчитать число комментариев;
      :Перестроить дерево обсуждения;
      |Модератор|
      :Комментарий удалён;
      stop
    endif
  endif
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D58
skinparam monochrome true
title Диаграмма 58/62 — UC-29. Взятие тикета в работу (деятельность)
|Модератор|
start
:Открыть чат поддержки;
|Система|
if (Роль\nмодератора?) then ([нет])
  :Вернуть 403;
  |Модератор|
  :Очередь недоступна;
  stop
else ([да])
  |Система|
  :Загрузить тикеты со статусом open;
  :Показать блок «Свободные вопросы»;
  |Модератор|
  while (Есть свободные\nтикеты?) is ([да])
    :Выбрать тикет из очереди;
    :Нажать «Взять в работу»;
    |Система|
    :Выполнить атомарный UPDATE\nпо статусу open;
    if (Тикет\nзахвачен?) then ([да])
      :Записать moderator_id\nи статус assigned;
      :Обновить отметку времени тикета;
      :Открыть чат выбранного тикета;
      :Загрузить переписку тикета;
      |Модератор|
      :Приступить к общению с пользователем;
      stop
    else ([нет])
      |Система|
      :Вернуть 409 «Тикет уже занят»;
      :Обновить очередь свободных тикетов;
      |Модератор|
      :Выбрать другой тикет;
    endif
  endwhile ([нет])
  :Все свободные вопросы разобраны;
  stop
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D60
skinparam monochrome true
title Диаграмма 60/62 — UC-30. Закрытие тикета (деятельность)
|Модератор|
start
:Убедиться, что вопрос решён;
note right
  Кнопка «Закрыть» доступна
  только модератору и админу
end note
:Нажать «Закрыть» в чате тикета;
|Система|
:Запросить подтверждение закрытия;
if (Подтверждение\nполучено?) then ([нет])
  |Модератор|
  :Оставить тикет открытым;
  stop
else ([да])
  |Система|
  if (Роль\nмодератора?) then ([нет])
    :Вернуть 403;
    |Модератор|
    :Закрытие отклонено;
    stop
  else ([да])
    |Система|
    :Выполнить UPDATE\nпо активному статусу;
    if (Тикет был\nактивен?) then ([нет])
      :Вернуть 404;
      |Модератор|
      :Обновить список обращений;
      stop
    else ([да])
      |Система|
      :Установить статус closed;
      :Обновить отметку времени тикета;
      fork
        :Скрыть поле ввода и кнопку закрытия;
      fork again
        :Сохранить переписку в истории;
      end fork
      |Пользователь|
      :Увидеть при опросе,\nчто обращение закрыто;
      :Просмотреть сохранённую переписку;
      stop
    endif
  endif
endif
@enduml",
  "config": null
}

{
  "data": "@startuml D62
skinparam monochrome true
title Диаграмма 62/62 — UC-31. Управление пользователями Бан/Разбан (деятельность)
|Администратор|
start
:Открыть панель управления\nпользователями;
|Система|
if (Роль\nadmin?) then ([нет])
  :Вернуть 403;
  |Администратор|
  :Доступ к панели запрещён;
  stop
else ([да])
  |Система|
  :Загрузить список учётных записей;
  :Показать login, email, роль,\nстатус и last_login;
  |Администратор|
  while (Есть записи\nдля обработки?) is ([да])
    :Выбрать учётную запись;
    if (Своя запись или\nдругой админ?) then ([да])
      :Операция блокировки недоступна;
    else ([нет])
      |Администратор|
      if (Нужна\nблокировка?) then ([да])
        :Нажать «Заблокировать»;
      else ([нет])
        :Нажать «Разблокировать»;
      endif
      |Система|
      :Запросить подтверждение операции;
      if (Подтверждение\nполучено?) then ([да])
        :Обновить статус banned или active;
        fork
          :Обновить таблицу пользователей;
        fork again
          :Применить статус при авторизации;
        end fork
        |Пользователь|
        :Выполнить вход в систему;
        |Система|
        if (Статус\nactive?) then ([да])
          :Пропустить пользователя в каталог;
        else ([нет])
          :Вернуть 403 «Аккаунт заблокирован»;
        endif
      else ([нет])
        |Система|
        :Оставить статус без изменения;
      endif
    endif
    |Администратор|
  endwhile ([нет])
  :Завершить сеанс администрирования;
  stop
endif
@enduml",
  "config": null
}
